-- Additional primary-source factory research for Triumph & Ducati.
-- Explicitly year and market scoped; never replicate to unlike factory variants.
with documented(catalog_model_id,category,label,value,start_year,end_year,market,source_name,source_url,verification_basis,scope_note,source_version) as (values
(663,'history','Triumph Bonneville T120 — modern 1200 cc T120 model revived for 2016','{"engine":"Liquid-cooled High Torque parallel twin","heritage":"Original T120 design unveiled in 1958, model''s 1959 heritage","engine_capacity_cc":1200,"modern_reintroduction":"2016"}'::jsonb,2016,NULL,'Triumph international model history','Triumph Motorcycles — Our Story: Bonneville family','https://www.triumphmotorcycles.com/our-story/bonneville','manufacturer_primary_source_exact_model_checked_2026_11_12','Triumph official model-family history differentiates historic 1958-1959 T120 and modern 2016 liquid-cooled T120; do not conflate historic and modern chassis.','Triumph Motorcycles — Our Story: Bonneville family'),
(663,'specification','Triumph Bonneville T120 — 2021 generation factory technical reference','{"power":"78 hp at 6,550 rpm","torque":"77 lb-ft at 3,500 rpm","gearbox":"Six speed","model_year":"2021","ride_modes":"Road and Rain","engine_type":"Liquid-cooled 270-degree parallel twin","front_brakes":"Twin Brembo front calipers with ABS","engine_capacity_cc":1200}'::jsonb,2021,NULL,'Triumph manufacturer 2021 model reference','Triumph Motorcycles — Bonneville T120 2021 MY technical details','https://www.triumphmotorcycles.com/motorcycles/prior-model-years/t120-2021-my','manufacturer_primary_source_exact_model_checked_2026_11_12','2021 Triumph manufacturer reference; not retroactively applied to historic or earlier Bonneville T120 generations.','Triumph Motorcycles — Bonneville T120 2021 MY technical details'),
(670,'specification','Triumph Speed Triple 1200 RS — 2022 factory model specification','{"power":"180 PS at 10,750 rpm","engine":"Liquid-cooled DOHC inline three-cylinder","torque":"92 lb-ft at 9,000 rpm","model_year":"2022","electronics":"Cornering ABS and traction control","front_brakes":"Brembo Stylema calipers and twin 320 mm discs","front_suspension":"Öhlins 43 mm NIX30 adjustable forks","engine_capacity_cc":1160}'::jsonb,2022,NULL,'Triumph 2022 manufacturer archive','Triumph Motorcycles — Speed Triple 1200 RS prior model year 2022','https://www.triumphmotorcycles.com/motorcycles/prior-model-years/speed-triple-1200-rs-2022','manufacturer_primary_source_exact_model_checked_2026_11_12','2022 prior model-year original specification; 2025 onward SmartEC3 update is distinct and should not inherit 2022 suspension figures.','Triumph Motorcycles — Speed Triple 1200 RS prior model year 2022'),
(748,'history','Ducati Monster 900 — first Monster M900 origin in 1992','{"concept":"Unfaired superbike-derived chassis for road use","model_lineage":"Foundation of Ducati''s Monster naked motorcycle family","original_model":"Monster M900","historical_reference_year":"1992"}'::jsonb,1992,NULL,'Ducati global company history','Ducati Media House — 350,000 Times Monster','https://mediahouse.ducati.com/350-000-times-monster-370605/?lang=eng','manufacturer_primary_source_exact_model_checked_2026_11_12','Ducati retrospective gives 1992 origin of the Monster M900; this is design/model family origin, not asserted as first UK customer registration date or a uniform production specification.','Ducati Media House — 350,000 Times Monster'),
(107,'model_year','Ducati Panigale V4 — 2020 factory aerodynamic and electronic revision','{"power":"214 metric hp at 13,000 rpm","model_year":"2020","electronics":"DTC EVO 2 and DQS EVO 2","engine_type":"90-degree desmodromic V4 Desmosedici Stradale","technical_changes":"V4 R-derived winglets and revised front frame","engine_capacity_cc":1103,"original_family_market_arrival":"2018"}'::jsonb,2020,NULL,'Ducati Europe / international 2020 model','Ducati Media House — New Panigale V4 MY2020 at dealerships, 20 January 2020','https://mediahouse.ducati.com/la-nouvelle-panigale-v4-2020-disponible-chez-les-distributeurs-ducati-374934/?lang=fra','manufacturer_primary_source_exact_model_checked_2026_11_12','Manufacturer''s French language 20 Jan 2020 release, translated for facts: figures and changes refer to 2020 standard Panigale V4, not later redesigns or Panigale V4 R.','Ducati Media House — New Panigale V4 MY2020 at dealerships, 20 January 2020')
)
insert into public.motorcycle_catalog_facts(catalog_model_id,category,label,value,start_year,end_year,market,source_name,source_url,verification_status)
select d.catalog_model_id,d.category,d.label,d.value,d.start_year,d.end_year,d.market,d.source_name,d.source_url,'verified' from documented d
where exists(select 1 from public.motorcycle_catalog_dropdown_clean m where m.model_id=d.catalog_model_id)
and not exists(select 1 from public.motorcycle_catalog_facts f where f.catalog_model_id=d.catalog_model_id and f.label=d.label and f.source_url=d.source_url);

with documented(catalog_model_id,label,source_url,verification_basis,scope_note,source_version) as (values
(663,'Triumph Bonneville T120 — modern 1200 cc T120 model revived for 2016','https://www.triumphmotorcycles.com/our-story/bonneville','manufacturer_primary_source_exact_model_checked_2026_11_12','Triumph official model-family history differentiates historic 1958-1959 T120 and modern 2016 liquid-cooled T120; do not conflate historic and modern chassis.','Triumph Motorcycles — Our Story: Bonneville family'),
(663,'Triumph Bonneville T120 — 2021 generation factory technical reference','https://www.triumphmotorcycles.com/motorcycles/prior-model-years/t120-2021-my','manufacturer_primary_source_exact_model_checked_2026_11_12','2021 Triumph manufacturer reference; not retroactively applied to historic or earlier Bonneville T120 generations.','Triumph Motorcycles — Bonneville T120 2021 MY technical details'),
(670,'Triumph Speed Triple 1200 RS — 2022 factory model specification','https://www.triumphmotorcycles.com/motorcycles/prior-model-years/speed-triple-1200-rs-2022','manufacturer_primary_source_exact_model_checked_2026_11_12','2022 prior model-year original specification; 2025 onward SmartEC3 update is distinct and should not inherit 2022 suspension figures.','Triumph Motorcycles — Speed Triple 1200 RS prior model year 2022'),
(748,'Ducati Monster 900 — first Monster M900 origin in 1992','https://mediahouse.ducati.com/350-000-times-monster-370605/?lang=eng','manufacturer_primary_source_exact_model_checked_2026_11_12','Ducati retrospective gives 1992 origin of the Monster M900; this is design/model family origin, not asserted as first UK customer registration date or a uniform production specification.','Ducati Media House — 350,000 Times Monster'),
(107,'Ducati Panigale V4 — 2020 factory aerodynamic and electronic revision','https://mediahouse.ducati.com/la-nouvelle-panigale-v4-2020-disponible-chez-les-distributeurs-ducati-374934/?lang=fra','manufacturer_primary_source_exact_model_checked_2026_11_12','Manufacturer''s French language 20 Jan 2020 release, translated for facts: figures and changes refer to 2020 standard Panigale V4, not later redesigns or Panigale V4 R.','Ducati Media House — New Panigale V4 MY2020 at dealerships, 20 January 2020')
)
insert into public.motorcycle_catalog_fact_verification_audit(fact_id,checked_at,verification_basis,source_url,scope_note,source_version)
select f.id,now(),d.verification_basis,d.source_url,d.scope_note,d.source_version
from documented d join public.motorcycle_catalog_facts f on f.catalog_model_id=d.catalog_model_id and f.label=d.label and f.source_url=d.source_url
where not exists(select 1 from public.motorcycle_catalog_fact_verification_audit a where a.fact_id=f.id);
